#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Finalize v1.5.30 original-vision completion with causal transitions and research."""
from pathlib import Path
import re, json
ROOT=Path(__file__).resolve().parents[1]

def rd(p): return (ROOT/p).read_text(encoding='utf-8')
def wr(p,s): (ROOT/p).write_text(s,encoding='utf-8')
def need(s,old,new,label):
    if old not in s: raise SystemExit('missing '+label)
    return s.replace(old,new,1)

def patch_build_data():
    p='scripts/build_data.py';s=rd(p)
    if 'breakout_volume_median20' not in s:
        s=need(s,'    p20 = h.shift(1).rolling(20).max()\n\n    row = {','''    p20 = h.shift(1).rolling(20).max()\n    # v1.5.30: causal self baselines. Average volume excludes the current day;\n    # breakout-event volume uses only prior completed 20-day breakout events.\n    avgvol20 = v.shift(1).rolling(20).mean()\n    breakout_mask = (c > p20) & p20.notna()\n    hist_breakout_vol = v.iloc[:-1][breakout_mask.iloc[:-1]].dropna().tail(20)\n\n    row = {''','breakout history setup')
        s=need(s,'        "avg_turnover20": float((c*v).rolling(20).mean().iloc[-1]),\n        "date": str(x.index[-1].date()),','''        "volume": float(v.iloc[-1]),\n        "avg_volume20": float(avgvol20.iloc[-1]) if pd.notna(avgvol20.iloc[-1]) else None,\n        "breakout_event_count": int(len(hist_breakout_vol)),\n        "breakout_volume_median20": float(hist_breakout_vol.median()) if len(hist_breakout_vol) >= 3 else None,\n        "breakout_volume_avg20": float(hist_breakout_vol.mean()) if len(hist_breakout_vol) >= 3 else None,\n        "avg_turnover20": float((c*v).rolling(20).mean().iloc[-1]),\n        "date": str(x.index[-1].date()),''','daily baseline fields')
    wr(p,s)

def patch_completion():
    p='scripts/build_completion.py';s=rd(p)
    new_chip='''def enrich_chip(r):\n    net_raw=r.get("foreign_3d_net")\n    avgvol=f(r.get("avg_volume20"))\n    strength=None\n    if net_raw is not None and avgvol>0:\n        # TWSE/TPEx institutional fields are 股數; Yahoo Volume is shares. Units match directly.\n        strength=round(float(net_raw)/avgvol*100,2)\n    r["foreign_3d_strength_pct"]=strength\n    r["foreign_strength_unit"]="shares / prior20d_avg_shares"\n    r["chip_force_label"]="資料不足" if strength is None else ("強力買超" if strength>=15 else "明顯買超" if strength>=5 else "小幅買超" if strength>0 else "偏賣超" if strength<0 else "中性")\n'''
    s,n=re.subn(r'def enrich_chip\(r\):.*?(?=def breakout_baseline)',new_chip,s,flags=re.S)
    if n!=1: raise SystemExit('enrich_chip replace failed')
    new_main='''def main(mode):\n    path=DATA/("intraday.json" if mode=="intraday" else "close.json")\n    obj=load(path,{}); rows=obj.get("rows") or []\n    hist=load(HIST,{"date":None,"codes":{},"transitions":[],"sector_accel":{}})\n    today=datetime.now(TW).date().isoformat(); now=datetime.now(TW).isoformat(timespec="minutes")\n    if hist.get("date")!=today: hist={"date":today,"codes":{},"transitions":[],"sector_accel":{}}\n    hist.setdefault("transitions",[]); hist.setdefault("sector_accel",{})\n    for r in rows:\n        enrich_chip(r);breakout_baseline(r)\n        if mode=="intraday":\n            pattern(r); code=str(r.get("code") or ""); h=hist["codes"].setdefault(code,[])\n            snap={"t":r.get("quote_time") or r.get("time") or now,"score":f(r.get("intraday_score") or r.get("score")),"stage":r.get("category"),"pace":f(r.get("pace"),1),"rs":f((r.get("intraday_components") or {}).get("relative_strength")),"sector":f((r.get("intraday_components") or {}).get("sector")),"vwap_dist":f(r.get("vwap_dist")),"pattern":r.get("execution_pattern")}\n            previous=h[-1] if h else None\n            if not h or h[-1].get("t")!=snap["t"]: h.append(snap)\n            h[:]=h[-80:]\n            first=h[0] if h else snap; prev=h[-2] if len(h)>1 else first\n            oldstage=(previous or {}).get("stage"); newstage=snap.get("stage")\n            flags={\n                "entered_setup": bool(previous and oldstage!="蓄勢待發" and newstage=="蓄勢待發"),\n                "entered_launch": bool(previous and oldstage!="剛啟動" and newstage=="剛啟動"),\n                "became_overheat": bool(previous and oldstage!="過熱不追" and newstage=="過熱不追"),\n                "became_weak": bool(previous and oldstage not in {"轉弱警戒","結構失效"} and newstage in {"轉弱警戒","結構失效"}),\n            }\n            r["today_transitions"]=flags\n            for typ,hit in flags.items():\n                if hit:\n                    key=f"{code}:{typ}"\n                    if not any(x.get("key")==key for x in hist["transitions"]): hist["transitions"].append({"key":key,"code":code,"name":r.get("name"),"type":typ,"time":snap["t"]})\n            r["today_change_summary"]={"score_open_delta":round(snap["score"]-first["score"],1),"score_last_delta":round(snap["score"]-prev["score"],1),"pace_open":first["pace"],"pace_now":snap["pace"],"rs_open":first["rs"],"rs_now":snap["rs"],"stage_open":first["stage"],"stage_now":snap["stage"]}\n            d=r["today_change_summary"]["score_open_delta"]\n            r["today_direction"]="一路改善" if d>=10 and snap["score"]>=prev["score"] else "重新轉強" if snap["score"]-prev["score"]>=6 else "先強後弱" if d<=-8 else "持平整理"\n    if mode=="intraday":\n        for z in obj.get("sector_rotation") or []:\n            name=str(z.get("sector") or '').strip(); heat=f(z.get("heat")); state=str(z.get("state") or '')\n            if name and (heat>=5 or '流入加速' in state):\n                old=hist["sector_accel"].get(name) or {"sector":name,"first_time":now}\n                old.update({"latest_time":now,"heat":heat,"state":state}); hist["sector_accel"][name]=old\n        trans=hist.get("transitions") or []\n        dirs={}\n        for r in rows: dirs[r.get("today_direction")]=(dirs.get(r.get("today_direction"),0)+1)\n        today_radar={\n            "new_setup":sum(x.get("type")=="entered_setup" for x in trans),\n            "new_launch":sum(x.get("type")=="entered_launch" for x in trans),\n            "became_overheat":sum(x.get("type")=="became_overheat" for x in trans),\n            "became_weak":sum(x.get("type")=="became_weak" for x in trans),\n            "improving":dirs.get("一路改善",0),"restrengthening":dirs.get("重新轉強",0),\n            "sector_accel_count":len(hist["sector_accel"]),\n            "sector_accel":sorted(hist["sector_accel"].values(),key=lambda x:f(x.get("heat")),reverse=True),\n        }\n        obj["today_change_radar"]=today_radar\n        obj.setdefault("change_radar",{})["today"]=today_radar\n        dump(HIST,hist)\n    obj["completion_version"]="1.1";obj["completion_updated_at"]=datetime.now(TW).isoformat(timespec="seconds")\n    dump(path,obj)\n    st=load(DATA/"status.json",{});st.update({"version":"1.5.30-free","completion_version":"1.1"});dump(DATA/"status.json",st)\n    print("completion",mode,len(rows))\n'''
    s,n=re.subn(r'def main\(mode\):.*?(?=if __name__==)',new_main,s,flags=re.S)
    if n!=1: raise SystemExit('main replace failed')
    wr(p,s)

def patch_validation():
    p='scripts/build_validation.py';s=rd(p)
    # Ensure enriched features are archived on both layers.
    if '"foreign_3d_strength_pct": f(r.get("foreign_3d_strength_pct"))' not in s:
        s=s.replace('        "liquidity_level": r.get("liquidity_level"),\n        "components": {','        "liquidity_level": r.get("liquidity_level"),\n        "foreign_3d_strength_pct": f(r.get("foreign_3d_strength_pct")),\n        "breakout_volume_ratio": f(r.get("breakout_volume_ratio")),\n        "breakout_volume_baseline_mode": r.get("breakout_volume_baseline_mode"),\n        "components": {',1)
    if '"execution_pattern": r.get("execution_pattern")' not in s:
        s=s.replace('        "dynamic_thresholds": r.get("dynamic_thresholds") or {},\n    }','        "dynamic_thresholds": r.get("dynamic_thresholds") or {},\n        "execution_pattern": r.get("execution_pattern"),\n        "today_direction": r.get("today_direction"),\n        "today_change_summary": r.get("today_change_summary") or {},\n        "foreign_3d_strength_pct": f(r.get("foreign_3d_strength_pct")),\n        "breakout_volume_ratio": f(r.get("breakout_volume_ratio")),\n    }',1)
    # Carry research features into matured outcome rows.
    s=s.replace('                "components": r.get("components") or {}, "returns": {},','                "components": r.get("components") or {}, "returns": {},\n                "foreign_3d_strength_pct": r.get("foreign_3d_strength_pct"),\n                "breakout_volume_ratio": r.get("breakout_volume_ratio"),\n                "breakout_volume_baseline_mode": r.get("breakout_volume_baseline_mode"),',1)
    if 'def feature_research(' not in s:
        anchor='def summarize(records, calibration, history):\n'
        research='''def feature_research(records):\n    matured=[r for r in records if (r.get("returns") or {}).get("5") is not None]\n    def stat(items):\n        vals=[f((r.get("returns") or {}).get("5")) for r in items]; vals=[x for x in vals if x is not None]\n        return {"n":len(vals),"win_rate":round(sum(x>0 for x in vals)/len(vals)*100,1) if vals else None,"avg5":round(sum(vals)/len(vals),3) if vals else None,"median5":round(statistics.median(vals),3) if vals else None}\n    def chip_bucket(r):\n        x=f(r.get("foreign_3d_strength_pct"))\n        return "未知" if x is None else "強買≥15%" if x>=15 else "買5~15%" if x>=5 else "小買0~5%" if x>0 else "賣超≤0%"\n    def vol_bucket(r):\n        x=f(r.get("breakout_volume_ratio"))\n        return "未知" if x is None else "≥2x" if x>=2 else "1.3~2x" if x>=1.3 else "0.8~1.3x" if x>=.8 else "<0.8x"\n    by_chip={k:stat([r for r in matured if chip_bucket(r)==k]) for k in ["強買≥15%","買5~15%","小買0~5%","賣超≤0%"]}\n    by_vol={k:stat([r for r in matured if vol_bucket(r)==k]) for k in ["≥2x","1.3~2x","0.8~1.3x","<0.8x"]}\n    launched=[r for r in matured if r.get("category")=="剛啟動"]\n    fake=[r for r in launched if f((r.get("returns") or {}).get("5"),0)<=0 and f(r.get("mfe10"),0)<5]\n    combos={}\n    for r in matured:\n        key=f"{r.get('category') or '觀察'}｜{chip_bucket(r)}｜{vol_bucket(r)}"\n        combos.setdefault(key,[]).append(r)\n    combo_stats=[{"key":k,**stat(v)} for k,v in combos.items() if len(v)>=5]\n    combo_stats.sort(key=lambda x:(x.get("n") or 0,x.get("avg5") or -999),reverse=True)\n    return {"version":"1.0","status":"warming" if len(matured)<500 else "research_ready","matured_rows":len(matured),"chip_force_5d":by_chip,"breakout_volume_5d":by_vol,"fake_breakout":{"definition":"剛啟動後5日報酬<=0且10日MFE<5%","n":len(launched),"fake_n":len(fake),"fake_rate":round(len(fake)/len(launched)*100,1) if launched else None},"combinations":combo_stats[:30],"note":"研究層只描述歷史關聯，不直接改正式分數。"}\n\n\n'''
        s=s.replace(anchor,research+anchor,1)
    s=s.replace('        "calibration": calibration,\n        "recent_matured_signals": recent,','        "calibration": calibration,\n        "research": feature_research(records),\n        "recent_matured_signals": recent,',1)
    wr(p,s)

def patch_ui():
    p='docs/index.html';s=rd(p)
    # Replace the whole change radar function; this also removes literal \\n tokens accidentally inserted in v1.5.30 draft.
    fn='''function changeRadarHTML(){\n if(mode!=="intraday")return "";\n const x=changeRadar||{},c=x.counts||{},t=x.today||{};\n const heldWeak=(intraRows||[]).filter(r=>held(r.code)&&r.today_transitions?.became_weak).length;\n const overview=`<div class="changecounts"><span class="changecount">🌱今日新進蓄勢 ${t.new_setup||0}</span><span class="changecount">🔥今日新進剛啟動 ${t.new_launch||0}</span><span class="changecount">⬆️一路改善 ${t.improving||0}</span><span class="changecount">♻️重新轉強 ${t.restrengthening||0}</span><span class="changecount">⚠️庫存今日轉弱 ${heldWeak}</span><span class="changecount">🚫今日轉過熱 ${t.became_overheat||0}</span><span class="changecount">💰今日族群加速 ${t.sector_accel_count||0}</span></div>`;\n const head=`<div class="changetop"><div><div class="changetitle">🚨 今天值得注意</div><div class="changesub">今日累積事件＋最近5分鐘變化；「新進」只計真正從其他階段轉入，不是目前總檔數。</div></div></div>`;\n const counts=x.ready?`<div class="changecounts"><span class="changecount">⬆️5分轉強 ${c.turn_strong||0}</span><span class="changecount">⬇️5分轉弱 ${c.turn_weak||0}</span><span class="changecount">🚀剛突破 ${c.breakout||0}</span><span class="changecount">♻️剛站回VWAP ${c.vwap_reclaim||0}</span><span class="changecount">🔥族群剛加速 ${c.sector_accel||0}</span></div>`:"";\n const ev=(x.events||[]).slice(0,8);\n const items=x.ready?(ev.length?`<div class="changeevents">${ev.map(e=>`<button class="changeevent peerlink" data-code="${e.code}"><span class="changeeventmain"><span class="changeeventname">${e.label}｜${e.name} ${e.code}</span><div class="changeeventreason">${e.reason}</div></span><span class="changedelta">${e.score_delta===null||e.score_delta===undefined?"":signed(e.score_delta,0,"")}</span></button>`).join("")}</div>`:`<div class="changesub" style="margin-top:9px">這一輪沒有新的個股轉折訊號。</div>`):`<div class="changesub" style="margin-top:9px">5分鐘比較基準正在建立；今日累積事件仍持續保存。</div>`;\n const se=(t.sector_accel||[]).slice(0,5);\n const sectors=se.length?`<div class="sectorchange">今日曾進入資金加速：${se.map(e=>`${e.sector} ${signed(e.heat,1,"")}`).join(" · ")}</div>`:"";\n return `<div class="changebox">${head}${overview}${counts}${items}${sectors}</div>`;\n}\n\n'''
    s,n=re.subn(r'function changeRadarHTML\(\)\{.*?(?=function entryDecision\()',fn,s,flags=re.S)
    if n!=1: raise SystemExit('changeRadarHTML replace failed')
    # Add lightweight research status to validation panel without changing existing calibration logic.
    if '歷史組合研究' not in s:
        s=s.replace('${escHTML(c.guardrail||v.note||"樣本不足時正式權重維持50/25/15/10。")}</div>','${escHTML(c.guardrail||v.note||"樣本不足時正式權重維持50/25/15/10。")}</div><div class="validationnote">🔬 歷史組合研究：${v.research?.matured_rows||0} 筆成熟樣本｜剛啟動假突破率 ${v.research?.fake_breakout?.fake_rate==null?"—":num(v.research.fake_breakout.fake_rate,1)+"%"}｜只研究，不自動改分。</div>',1)
    wr(p,s)

def patch_status():
    p='docs/data/status.json';d=json.loads(rd(p));d['version']='1.5.30-free';d['completion_version']='1.1';wr(p,json.dumps(d,ensure_ascii=False,separators=(',',':'))+'\n')

if __name__=='__main__':
    patch_build_data();patch_completion();patch_validation();patch_ui();patch_status();print('v1.5.30 final completion patch applied')
